// Upgrades of the combinations (owner, 02.11.2026): after a won level the player picks one of three
// combinations to raise its multiplier by +1 for the rest of the run (`ups`, by category). The targets grow
// with the lift a sensible player gets from them (UP_LIFT, generated by scripts/upgrades3.mjs), so picking well
// is what keeps a player ahead.

import { createRng } from './rng.js';
import { AUTO_MULT } from './hands.js';
import { UP_SHARES } from './uplift3.js';

export const UP_CATEGORIES = Object.freeze(['pair', 'two_pairs', 'small_straight', 'three_kind', 'full_house', 'straight', 'four_kind', 'five_kind']);
export const UP_OFFER = 3;

// The three combinations offered after winning `levelIndex` (seeded: a reload shows the same three).
export function upgradeOffer(runSeed, levelIndex) {
  const rng = createRng(`${runSeed}/A${levelIndex}/upgrade`);
  const pool = UP_CATEGORIES.slice();
  const offer = [];
  while (offer.length < UP_OFFER) offer.push(pool.splice(rng.int(pool.length), 1)[0]);
  return offer;
}

export const withUpgrade = (ups = {}, category) => ({ ...ups, [category]: (ups[category] || 0) + 1 });

// The score lift of a set of upgrades: each combination's share of the points × its new multiplier over its
// base one (a model: a player who upgrades a combination also plays it a little more, so this undercounts).
export function upLift(ups = {}) {
  return UP_CATEGORIES.reduce((s, c) => s + (UP_SHARES[c] || 0) * ((AUTO_MULT[c] + (ups[c] || 0)) / AUTO_MULT[c]), 0);
}

// The sensible pick: the offered combination whose +1 adds the most points (its share over its multiplier).
export const sensiblePick = (offer) => offer.reduce((a, b) => ((UP_SHARES[b] || 0) / AUTO_MULT[b] > (UP_SHARES[a] || 0) / AUTO_MULT[a] ? b : a));
